#[derive(Debug, Clone, PartialEq)]
pub struct NvStorageOp {
    pub tag: NvEntryTag,
    pub length: i32,
    pub op: NvOperation,
    pub unknown: u8,
    pub data: Vec<u8>,
}

impl NvStorageOp {
    pub const NAME: &'static str = "NvStorageOp";
    /// Field names, in wire order.
    pub const FIELDS: &'static [&'static str] = &["tag", "length", "op", "unknown", "data"];
    pub const ID: Option<u8> = Some(0x81);
    pub const PACKET_TYPE: PacketType = PacketType::Command;
    /// The message with the declared default values (fails like PyCozmo when a default is invalid).
    pub fn try_default() -> Result<Self> {
        Ok(Self {
            tag: NvEntryTag::from_value(4294967295)?,
            length: 0_i32,
            op: NvOperation::from_value(0)?,
            unknown: 0_u8,
            data: vec![],
        })
    }
    /// Size of the encoded message.
    pub fn encoded_len(&self) -> usize {
        4 + 4 + 1 + 1 + 2 + self.data.len() * 1
    }
    /// Encodes the message.
    pub fn encode(&self, w: &mut Writer) -> Result<()> {
        w.write_int('L', self.tag.value())?;
        w.write_i32(self.length);
        w.write_int('B', self.op.value())?;
        w.write_u8(self.unknown);
        w.write_int('H', self.data.len() as i64)?;
        for e in &self.data {
            w.write_u8(*e);
        }
        Ok(())
    }
    /// Decodes the message.
    pub fn decode(r: &mut Reader<'_>) -> Result<Self> {
        let tag = i64::from(r.read_u32()?);
        let length = r.read_i32()?;
        let op = i64::from(r.read_u8()?);
        let unknown = r.read_u8()?;
        let data = {
            let n = r.read_u16()?;
            (0..n).map(|_| Ok(r.read_u8()?)).collect::<Result<Vec<_>>>()?
        };
        let tag = NvEntryTag::from_value(tag)?;
        let op = NvOperation::from_value(op)?;
        Ok(Self { tag, length, op, unknown, data })
    }
}

